import { forwardRef, useState } from "react";
import { PieChart, ResponsiveContainer } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { ChartClasses, StyledChart } from "./chart.styles";
import { ChartContext } from "./hooks/use-chart";
import { useDonutChart } from "./hooks/use-donut-chart";
import { DonutChartProps } from "./chart.types";

const DonutChart = forwardRef<HTMLDivElement, DonutChartProps>(
  (
    {
      children,
      className,
      style,
      styleSlots,
      variant = "default",
      innerRadius = "75%",
      outerRadius = "100%",
      showActivePieLabels,
      margin = { top: 10, right: 10, left: 10, bottom: 10 },
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [activeIndex, setActiveIndex] = useState<number | undefined>();
    const { chartChildren, numCategoricalColors } = useDonutChart(children, {
      innerRadius,
      outerRadius,
      ...(showActivePieLabels && {
        activeIndex,
        onMouseLeave: () => setActiveIndex(undefined),
        onMouseEnter: (_: unknown, index: number) => setActiveIndex(index),
      }),
    });

    return (
      <ChartContext.Provider
        value={{
          numCategoricalColors,
          showActivePieLabels,
        }}
      >
        <StyledChart
          ref={ref}
          className={clsx(ChartClasses.root, className)}
          currentTheme={theme}
          style={{ width: "100%", height: "100%", ...style }}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          <ResponsiveContainer
            className={ChartClasses.responsiveContainer}
            height="100%"
            width="100%"
          >
            <PieChart
              className={ChartClasses.donutChart}
              innerRadius={innerRadius}
              margin={margin}
              outerRadius={outerRadius}
            >
              {chartChildren}
            </PieChart>
          </ResponsiveContainer>
        </StyledChart>
      </ChartContext.Provider>
    );
  },
);

DonutChart.displayName = "DonutChart";

export default DonutChart;
